// Mini-clon de Express (solo lo necesario para esta prueba local, sin red).
import fs from 'node:fs';
import path from 'node:path';
import http from 'node:http';

function compilarRuta(p) {
  const keys = [];
  const patron = p.replace(/\/:([^/]+)/g, (_, k) => { keys.push(k); return '/([^/]+)'; });
  return { regex: new RegExp('^' + patron + '/?$'), keys };
}

function coincidePrefijo(prefijo, ruta) {
  if (prefijo === '' || prefijo === '/') return ruta || '/';
  if (ruta === prefijo) return '/';
  if (ruta.startsWith(prefijo + '/')) return ruta.slice(prefijo.length) || '/';
  return null;
}

function crearRouter() {
  const stack = [];
  function router(req, res, next) { despachar(stack, req, res, req._restante ?? req.path, next); }
  router.stack = stack;

  function registrar(metodo) {
    return (rutaOFn, ...resto) => {
      let ruta = '/', handlers = resto;
      if (typeof rutaOFn === 'string') { ruta = rutaOFn; } else { handlers = [rutaOFn, ...resto]; }
      const { regex, keys } = compilarRuta(ruta === '' ? '/' : ruta);
      stack.push({ metodo, regex, keys, handlers, esRouter: false });
    };
  }
  router.get = registrar('GET');
  router.post = registrar('POST');
  router.put = registrar('PUT');
  router.patch = registrar('PATCH');
  router.delete = registrar('DELETE');

  router.use = (prefijoOFn, ...resto) => {
    let prefijo = '', handlers;
    if (typeof prefijoOFn === 'string') { prefijo = prefijoOFn; handlers = resto; }
    else { handlers = [prefijoOFn, ...resto]; }
    for (const h of handlers) stack.push({ metodo: null, prefijo, handler: h, esMontaje: true });
  };

  return router;
}

// Ejecuta una cadena de capas (router raíz o anidado) sobre la ruta restante.
function despachar(stack, req, res, rutaRestante, salidaFinal) {
  let i = 0;
  function siguiente(err) {
    if (res.writableEnded) return;
    while (i < stack.length) {
      const capa = stack[i++];
      const esManejadorError = typeof (capa.handler || capa.handlers?.[0]) === 'function' &&
        (capa.handlers ? capa.handlers.some((h) => h.length === 4) : capa.handler.length === 4);

      if (err) {
        if (capa.esMontaje && capa.handler?.length === 4) {
          try { const r = capa.handler(err, req, res, siguiente); if (r?.catch) r.catch(siguiente); } catch (e) { siguiente(e); }
          return;
        }
        continue; // saltar capas normales mientras hay un error activo
      }

      if (capa.esMontaje) {
        const resto = coincidePrefijo(capa.prefijo, rutaRestante);
        if (resto == null) continue;
        req._restante = resto;
        if (capa.handler.stack) { despachar(capa.handler.stack, req, res, resto, siguiente); return; }
        if (capa.handler.length === 4) continue; // los manejadores de error no se ejecutan en flujo normal
        try {
          const r = capa.handler(req, res, siguiente);
          if (r?.catch) r.catch(siguiente);
        } catch (e) { siguiente(e); }
        return;
      }

      if (capa.metodo && capa.metodo !== req.method) continue;
      const m = capa.regex.exec(rutaRestante);
      if (!m) continue;
      req.params = {};
      capa.keys.forEach((k, idx) => { req.params[k] = decodeURIComponent(m[idx + 1]); });
      ejecutarHandlers(capa.handlers, 0, req, res, siguiente);
      return;
    }
    salidaFinal ? salidaFinal(err) : finalizarSinRuta(req, res);
  }
  siguiente();
}

function ejecutarHandlers(handlers, idx, req, res, siguienteExterno) {
  function siguiente(err) {
    if (res.writableEnded) return;
    if (err) return siguienteExterno(err);
    if (idx >= handlers.length) return siguienteExterno();
    const h = handlers[idx++];
    try {
      const r = h(req, res, siguiente);
      if (r?.catch) r.catch(siguienteExterno);
    } catch (e) { siguienteExterno(e); }
  }
  siguiente();
}

function finalizarSinRuta(req, res) {
  res.statusCode = 404;
  res.setHeader('Content-Type', 'application/json');
  res.end(JSON.stringify({ error: 'No encontrado' }));
}

function express() {
  const app = crearRouter();
  app.listen = (port, cb) => {
    const server = http.createServer((req, res) => {
      const u = new URL(req.url, 'http://localhost');
      req.path = u.pathname;
      req.query = Object.fromEntries(u.searchParams);
      const chunks = [];
      req.on('data', (c) => chunks.push(c));
      req.on('end', () => {
        req._rawBody = Buffer.concat(chunks);
        res.status = (code) => { res.statusCode = code; return res; };
        res.json = (obj) => { res.setHeader('Content-Type', 'application/json'); res.end(JSON.stringify(obj)); };
        res.download = (filePath, filename) => {
          fs.readFile(filePath, (err, data) => {
            if (err) { res.statusCode = 404; return res.end(JSON.stringify({ error: 'Archivo no encontrado' })); }
            res.setHeader('Content-Disposition', `attachment; filename="${filename || path.basename(filePath)}"`);
            res.end(data);
          });
        };
        try { app(req, res); } catch (e) { res.statusCode = 500; res.end(JSON.stringify({ error: 'Error interno del servidor' })); }
      });
    });
    server.listen(port, cb);
    return server;
  };
  return app;
}

express.json = (opts = {}) => (req, res, next) => {
  const ct = req.headers['content-type'] || '';
  if (!ct.includes('application/json')) return next();
  try {
    req.body = req._rawBody.length ? JSON.parse(req._rawBody.toString('utf8')) : {};
    next();
  } catch (e) { next(e); }
};

express.static = (dir) => (req, res, next) => {
  const rel = decodeURIComponent((req._restante || req.path || '/').replace(/^\/+/, ''));
  if (!rel || rel.includes('..')) return next();
  const full = path.join(dir, rel);
  fs.readFile(full, (err, data) => {
    if (err) return next();
    const ext = path.extname(full).toLowerCase();
    const tipo = { '.png': 'image/png', '.jpg': 'image/jpeg', '.jpeg': 'image/jpeg', '.webp': 'image/webp', '.gif': 'image/gif' }[ext] || 'application/octet-stream';
    res.setHeader('Content-Type', tipo);
    res.end(data);
  });
};

export function Router() { return crearRouter(); }
export default express;
